#include <iostream>
#include <string>
#include <variant>
#include <vector>
using namespace std;

enum class FieldType { INT, STRING, DOUBLE };

struct FieldRule { string name; FieldType type; double min, max; };
struct Field { string name; variant<int, string, double> value; };

bool validate(const FieldRule& rule, const Field& field) {
    switch (rule.type) {
        case FieldType::INT: {
            int val = get<int>(field.value);
            return val >= rule.min && val <= rule.max;
        }
        case FieldType::STRING: {
            int len = get<string>(field.value).length();
            return len >= rule.min && len <= rule.max;
        }
        default: return false;
    }
}

int main() {
    FieldRule rules[] = {{"age", FieldType::INT, 0, 150}, {"name", FieldType::STRING, 1, 50}};
    Field fields[] = {{"age", 25}, {"name", string("Alice")}};
    for (int i = 0; i < 2; i++)
        cout << fields[i].name << ": " << (validate(rules[i], fields[i]) ? "OK" : "INVALID") << endl;

    Field badField = {"age", -5};
    cout << badField.name << ": " << (validate(rules[0], badField) ? "OK" : "INVALID") << endl;
    return 0;
}
